'use strict';

var linspace = require( '@stdlib/array/base/linspace' );
var airy = require( './../lib' );

var out;
var i;
var x = linspace( 0.0, 10.0, 100 );

for ( i = 0; i < 100; i++ ) {
	out = airy( x[ i ] );
	console.log( 'Ai(%d) = %d', x[ i ], out[ 0 ] );
	console.log( 'Ai\'(%d) = %d', x[ i ], out[ 1 ] );
	console.log( 'Bi(%d) = %d', x[ i ], out[ 2 ] );
	console.log( 'Bi\'(%d) = %d', x[ i ], out[ 3 ] );
}
